import{S as n,o as t,c as h,a9 as p,B as l}from"./chunks/framework.DxG24V0C.js";const k="/agentsrc/images/opencode/02-layers.svg",e="/agentsrc/images/opencode/02-loop.svg",E="/agentsrc/images/opencode/02-doom.svg",y=JSON.parse('{"title":"OpenCode 主循环图解：一条消息是怎么跑完整个 Agent 的？","description":"","frontmatter":{"title":"OpenCode 主循环图解：一条消息是怎么跑完整个 Agent 的？"},"headers":[],"relativePath":"opencode/02-runloop.md","filePath":"opencode/02-runloop.md","lastUpdated":1788319991000}'),r={name:"opencode/02-runloop.md"},c=Object.assign(r,{setup(d){const i=[{question:"OpenCode 为什么把 `prompt()`、`loop()`、`runLoop()` 拆成三层，而不是都塞进一个入口函数？",options:["因为 Effect 写法要求入口函数必须拆成三段","因为输入、并发、编排属于三种不同复杂度","因为 TypeScript 单文件函数超过长度后性能会下降","因为工具系统只能从单独的 loop 函数中读取配置"],correct:1,explanation:"这三层分别处理消息写入、会话并发控制和主循环编排，是对三种复杂度的边界拆分。不是 Effect 的语法要求，也不是 TypeScript 性能问题。工具系统也不是因此才可用。"},{question:"OpenCode 为什么不把工具调用单独写成一层 `while` 循环？",options:["因为工具调用都由数据库触发，无法在内存里循环","因为工具调用的作用是让主循环的退出条件暂不成立","因为 AI SDK 不支持连续两轮之间保留工具上下文","因为工具执行和模型调用必须分属两条不同的 session 控制流"],correct:1,explanation:"OpenCode 没把工具调用拆成独立循环——一旦拆开，工具循环和主循环就成了两套互相通信的状态机。它选择让工具调用只是让主循环的退出条件暂不成立：只要模型发出工具请求、或消息流里还有未处理的 tool part，session 就没到可退出状态，主循环自然进入下一轮。不拆并不是做不到，而是为了避免多加一套平行循环；这跟数据库、AI SDK 或 session 控制流拆分都没有关系。"},{question:"为什么 `filterCompactedEffect()` 会在每一轮主循环开头重新执行？",options:["因为上一轮的消息对象会在下一轮被垃圾回收，必须重建","因为 compaction 之后模型可见顺序与数据库原始顺序可能不同","因为 OpenCode 每轮都会重新生成 system prompt，必须清空旧消息","因为工具结果只能在下一轮被转成 user message 重新发送"],correct:1,explanation:"做过 compaction 后，模型应看到的是“摘要 + 保留尾巴”的重排结果，不一定等于数据库中原始消息排列。所以每轮都要重新推导当前可消费上下文，而不是依赖上一轮内存状态。"},{question:"从主循环角度看，compaction 在 OpenCode 里更接近哪种角色？",options:["一种普通调度分支，与 subtask 一样属于待处理工作","一种只在 provider 报错后才启动的异常修复补丁","一种专门属于工具系统的后处理步骤","一种只用于 structured output 的模型格式化机制"],correct:0,explanation:"OpenCode 把 compaction 显式建模为 task，并在主循环里与 subtask、overflow 检查并列处理，所以它是常规调度路径的一部分，而不是只在异常后才进入的补丁，也不属于工具后处理或结构化输出。"},{question:"Doom Loop 检测最能体现 OpenCode 的哪种设计取向？",options:["框架发现重复后直接封禁，优先保证执行效率","框架发现重复后交给权限系统判断，而不是武断地拦截","框架通过增加重试次数来消化重复调用，减少人工干预","框架把重复工具调用自动改写成批处理请求，避免循环"],correct:1,explanation:"OpenCode 识别到连续重复调用后，不直接 ban，而是走权限询问。因为重复本身可能是合法策略，系统要拦的是“没有进展的重复”。其他选项都不是源码里的实际策略。"}];return(g,s)=>{const a=n("Quiz");return t(),h("div",null,[s[0]||(s[0]=p("",142)),l(a,{questions:i})])}}});export{y as __pageData,c as default};
